var q = [tree.root]
var out := []
while not q.is_empty():
	var c = q.pop_front()
	if c is ItemList and c.is_visible_in_tree():
		for i in range(c.item_count):
			out.append(str(c.get_item_text(i)))
	elif (c is Label or c is Button or c is RichTextLabel) and c.is_visible_in_tree():
		out.append(str(c.get_parsed_text()) if c is RichTextLabel else str(c.text))
	for ch in c.get_children():
		q.append(ch)
return out.any(func(t): return t.contains("Kustom shoota") and t.contains("Custodian"))

